2476	/**
2477	 * 出报表前核对完整库存流水（只读核对，不自动修复）：
2478	 * 1) 同一（商品, 仓库）的流水按提交顺序余量连续（上笔后量 = 下笔前量）；
2479	 * 2) 调拨/冲销调拨同一单据同一商品两端完整（调出、调入各一条，数量与方向一致）；
2480	 * 3) 每个组合末笔余量与当前实存一致（双向：有流水无实存、有实存无流水均不允许）。
2481	 * 任一不一致明确报错（数据损坏，退出 1），不输出部分报表。
2482	 */
2483	function verifyLedgerIntegrity(store: Store): void {
2484	  const lastByCombo = new Map<string, LedgerEntry>();
2485	  for (const e of store.entries) {
2486	    const key = JSON.stringify([e.product, e.wh]);
2487	    const prev = lastByCombo.get(key);
2488	    if (prev !== undefined && prev.after !== e.before)
2489	      throw new DataError(
2490	        `库存流水余量不连续：商品 ${e.product} 仓库 ${e.wh} 流水 #${prev.seq} 后余量 ${prev.after}，` +
2491	          `流水 #${e.seq} 前余量 ${e.before}，数据不一致，拒绝输出对账报表（不自动修复）`,
2492	      );
2493	    lastByCombo.set(key, e);
2494	  }
2495	  for (const [key, e] of lastByCombo) {
2496	    const [pid, wh] = JSON.parse(key) as [string, string];
2497	    const cur = getStock(store.stock, pid, wh);
2498	    if (e.after !== cur)
2499	      throw new DataError(
2500	        `商品 ${pid} 仓库 ${wh} 末笔流水 #${e.seq} 余量 ${e.after} 与当前实存 ${cur} 不一致，` +
2501	          `数据不一致，拒绝输出对账报表（不自动修复）`,
2502	      );
2503	  }
2504	  for (const pid of Object.keys(store.stock)) {
2505	    for (const wh of Object.keys(store.stock[pid])) {
2506	      if (store.stock[pid][wh] !== 0 && !lastByCombo.has(JSON.stringify([pid, wh])))
2507	        throw new DataError(
2508	          `商品 ${pid} 仓库 ${wh} 当前实存 ${store.stock[pid][wh]} 没有任何库存流水支撑，` +
2509	            `数据不一致，拒绝输出对账报表（不自动修复）`,
2510	        );
2511	    }
2512	  }
2513	  // 调拨两端完整性：同一单据同一商品的调拨（或冲销调拨）必须调出、调入各一条，数量与方向一致
2514	  const sides = new Map<string, LedgerEntry[]>();
2515	  for (const e of store.entries) {
2516	    if (e.type !== 'transfer' && e.type !== 'transfer-rev') continue;
2517	    const key = JSON.stringify([e.doc, e.product, e.type]);
2518	    const list = sides.get(key);
2519	    if (list === undefined) sides.set(key, [e]);
2520	    else list.push(e);
2521	  }
2522	  for (const [key, list] of sides) {
2523	    const [doc, product, type] = JSON.parse(key) as [string, string, EntryType];
2524	    const label = TYPE_LABEL[type];
2525	    if (list.length !== 2)
2526	      throw new DataError(
2527	        `${label}流水两端不完整：单据 ${doc} 商品 ${product} 只有 ${list.length} 条流水，` +
2528	          `数据不一致，拒绝输出对账报表（不自动修复）`,
2529	      );
2530	    const [a, b] = list;
2531	    const whPair = [a.wh, b.wh].sort();
2532	    const expect = [a.from!, a.to!].sort();
2533	    if (
2534	      a.from !== b.from || a.to !== b.to || a.qty !== b.qty ||
2535	      whPair[0] !== expect[0] || whPair[1] !== expect[1]
2536	    )
2537	      throw new DataError(
2538	        `${label}流水两端不一致：单据 ${doc} 商品 ${product} 的调出/调入仓或数量不符，` +
2539	          `数据不一致，拒绝输出对账报表（不自动修复）`,
2540	      );
2541	  }
2542	}
