2555	/**
2556	 * 期间库存对账报表（只读：不创建或改写数据、历史结果及关联）。
2557	 * 起点表示该单全部流水完成后的状态（期间不含起点），终点包含该单全部流水；
2558	 * 同一单作两端为空期间；不指定起点从零库存开始，不指定终点截至当前。
2559	 * 边界仅接受已成功且有库存流水的单据（冲销单、零差额盘点可用；只有采购或取消
2560	 * 记录的编号不可用；同名采购单不干扰库存单定位），按首次提交顺序（流水序号）
2561	 * 比较，起点晚于终点或单据不存在拒绝。先确定全局边界再按商品/仓库筛选，
2562	 * 不拆开多商品单据或调拨两端。
2563	 */
2564	function runRecon(rest: string[], store: Store): void {
2565	  const args = parseArgs(rest, ['--from', '--to', '--product', '--wh']);
2566	  if (args.positionals.length > 0)
2567	    throw new UsageError(
2568	      '用法：recon [--from <起点单据编号>] [--to <终点单据编号>] [--product <商品编号>] [--wh <仓库>]',
2569	    );
2570	  const fromId =
2571	    args.flags['--from'] === undefined ? undefined : trimOrThrow('起点单据编号', args.flags['--from']);
2572	  const toId =
2573	    args.flags['--to'] === undefined ? undefined : trimOrThrow('终点单据编号', args.flags['--to']);
2574	  const pid =
2575	    args.flags['--product'] === undefined ? undefined : trimOrThrow('商品编号', args.flags['--product']);
2576	  const wid = args.flags['--wh'] === undefined ? undefined : trimOrThrow('仓库标识', args.flags['--wh']);
2577	
2578	  // 出报表前核对完整库存流水；不一致明确报错，不输出部分报表、不自动修复
2579	  verifyLedgerIntegrity(store);
2580	
2581	  // 边界定位（全局）：仅接受有库存流水的单据编号；采购编号空间独立，同名采购不干扰定位
2582	  const docLastSeq = nullProto<Record<string, number>>();
2583	  for (const e of store.entries) docLastSeq[e.doc] = e.seq;
2584	  const boundary = (id: string, label: string): number => {
2585	    const seq = docLastSeq[id];
2586	    if (seq !== undefined) return seq;
2587	    if (store.purchases[id] !== undefined)
2588	      throw new BizError(`${label}单据 ${id} 只有采购登记记录，没有库存流水，不能用作期间边界`);
2589	    if (store.cancels[id] !== undefined)
2590	      throw new BizError(`${label}单据 ${id} 只有取消记录，没有库存流水，不能用作期间边界`);
2591	    if (store.reversals[id] !== undefined)
2592	      throw new BizError(`${label}单据 ${id} 是冲销取消单的冲销单，没有库存流水，不能用作期间边界`);
2593	    throw new BizError(`${label}单据 ${id} 不存在或没有库存流水，不能用作期间边界`);
2594	  };
2595	  const startBound = fromId === undefined ? 0 : boundary(fromId, '起点');
2596	  const endBound = toId === undefined ? Number.POSITIVE_INFINITY : boundary(toId, '终点');
2597	  if (startBound > endBound)
2598	    throw new BizError(`起点单据 ${fromId} 的提交顺序晚于终点单据 ${toId}，期间无效，拒绝生成报表`);
2599	
2600	  // 先确定全局边界，再按商品/仓库筛选；期间 = (起点末笔流水, 终点末笔流水]
2601	  const beginOf = nullProto<Record<string, Record<string, number>>>();
2602	  const endOf = nullProto<Record<string, Record<string, number>>>();
2603	  const combos = new Map<string, ReconCombo>();
2604	  const periodEntries: LedgerEntry[] = [];
2605	  for (const e of store.entries) {
2606	    if (e.seq <= startBound) (beginOf[e.product] ??= nullProto<Record<string, number>>())[e.wh] = e.after;
2607	    if (e.seq <= endBound) (endOf[e.product] ??= nullProto<Record<string, number>>())[e.wh] = e.after;
2608	    const match = (pid === undefined || e.product === pid) && (wid === undefined || e.wh === wid);
2609	    if (!match) continue;
2610	    const key = JSON.stringify([e.product, e.wh]);
2611	    if (e.seq <= endBound && !combos.has(key)) {
2612	      combos.set(key, {
2613	        pid: e.product, wh: e.wh, begin: 0, end: 0,
2614	        inc: 0n, dec: 0n, subtotals: new Map(), hasFlow: false,
2615	      });
2616	    }
2617	    if (e.seq > startBound && e.seq <= endBound) periodEntries.push(e);
2618	  }
2619	  for (const c of combos.values()) {
2620	    c.begin = beginOf[c.pid]?.[c.wh] ?? 0;
2621	    c.end = endOf[c.pid]?.[c.wh] ?? 0;
2622	  }
2623	  for (const e of periodEntries) {
2624	    const c = combos.get(JSON.stringify([e.product, e.wh]))!;
2625	    c.hasFlow = true;
2626	    const delta = BigInt(e.after) - BigInt(e.before);
2627	    if (delta > 0n) c.inc += delta;
2628	    else c.dec += -delta;
2629	    c.subtotals.set(e.type, (c.subtotals.get(e.type) ?? 0n) + delta);
2630	  }
2631	
