  private poHeader(poId: string, rec: PurchaseRecord): string {
    return `采购单 ${poId} 登记成功，供应商 ${rec.supplier}，收货仓 ${rec.wh}，共 ${Object.keys(rec.ordered).length} 种商品（登记不改动库存）：`;
