3036	interface ReplenishSuggestion {
3037	  pid: string;
3038	  wh: string;
3039	  min: number;
3040	  target: number;
3041	  onHand: number; // 本仓实存（非负安全整数）
3042	  pending: bigint; // 本仓待到货合计（精确整数，可超安全整数范围）
3043	  projected: bigint; // 预计量 = 实存 + 待到货合计
3044	  triggered: boolean; // 预计量不高于下限才触发
3045	  gap: bigint; // 缺口 = 目标 - 预计量（仅触发时为正）
3046	  transfers: { from: string; qty: bigint }[]; // 各调拨来源及数量（来源仓升序）
3047	  transferTotal: bigint; // 调拨合计
3048	  purchase: bigint; // 采购量 = 调拨后剩余缺口（可为零）
3049	}
