3051	/**
3052	 * 各（商品, 仓库）组合的待到货合计：按采购单收货仓归集（不限供应商），
3053	 * 待到货 = 订购 - 有效到货 - 有效取消；BigInt 精确累计，超安全整数合计不舍入。
3054	 * 补货建议与方案快照/核对共用同一计算，保证口径一致。
3055	 */
3056	function pendingTotals(store: Store): Record<string, Record<string, bigint>> {
3057	  const pendingByCombo = nullProto<Record<string, Record<string, bigint>>>();
3058	  for (const poId of Object.keys(store.purchases)) {
3059	    const po = store.purchases[poId];
3060	    const { remaining } = purchaseProgress(store, poId); // 待到货 = 订购 - 有效到货 - 有效取消
3061	    for (const [pid, wait] of Object.entries(remaining)) {
3062	      if (wait === 0n) continue;
3063	      const byWh = (pendingByCombo[pid] ??= nullProto<Record<string, bigint>>());
3064	      byWh[po.wh] = (byWh[po.wh] ?? 0n) + wait;
3065	    }
3066	  }
3067	  return pendingByCombo;
3068	}
