3070	/**
3071	 * 跨仓补货建议（只读计算，不写文件、不改库存或采购；同状态结果一致）：
3072	 * 每个已配置（商品, 仓库）组合的预计量 = 本仓实存 + 本仓待到货合计
3073	 * （收货仓为本仓的全部采购单：待到货 = 订购 - 有效到货 - 有效取消，不限供应商；
3074	 * 其他仓库存不计入）。预计量不高于下限才触发，缺口 = 目标 - 预计量。
3075	 * 按商品分别分配：同商品其他已配置仓实存超过自身目标的部分可供调拨（待收不可调，
3076	 * 未配置仓既不产生需求也不提供调拨）；缺货仓、来源仓各按标识升序依次取量，
3077	 * 整份建议对来源的累计分配不超过可供量；剩余缺口即采购量。
3078	 * 合计、比较与分配一律用 BigInt 精确整数计算。
3079	 */
3080	function computeReplenish(store: Store): ReplenishSuggestion[] {
3081	  // 各（商品, 仓库）组合的待到货合计：按采购单收货仓归集（不限供应商）
3082	  const pendingByCombo = pendingTotals(store);
3083	
3084	  const combos: ReplenishSuggestion[] = [];
3085	  for (const pid of Object.keys(store.rules).sort()) {
3086	    for (const wh of Object.keys(store.rules[pid]).sort()) {
3087	      const rule = store.rules[pid][wh];
3088	      const onHand = getStock(store.stock, pid, wh); // 无库存记录视为零
3089	      const pending = pendingByCombo[pid]?.[wh] ?? 0n;
3090	      const projected = BigInt(onHand) + pending;
3091	      const triggered = projected <= BigInt(rule.min); // 不高于下限才触发
3092	      combos.push({
3093	        pid, wh, min: rule.min, target: rule.target, onHand, pending, projected,
3094	        triggered, gap: triggered ? BigInt(rule.target) - projected : 0n,
3095	        transfers: [], transferTotal: 0n, purchase: 0n,
3096	      });
3097	    }
3098	  }
3099	
3100	  // 按商品分别分配调拨：缺货仓与来源仓均按标识升序（combos 已按商品、仓库升序）
3101	  const byProduct = new Map<string, ReplenishSuggestion[]>();
3102	  for (const c of combos) {
3103	    const list = byProduct.get(c.pid) ?? [];
3104	    list.push(c);
3105	    byProduct.set(c.pid, list);
3106	  }
3107	  for (const list of byProduct.values()) {
3108	    // 可供调拨量 = 实存 - 自身目标（仅实存超过目标的部分；待收不可调）
3109	    const sources = list
3110	      .filter((c) => BigInt(c.onHand) > BigInt(c.target))
3111	      .map((c) => ({ wh: c.wh, available: BigInt(c.onHand) - BigInt(c.target) }));
3112	    for (const deficit of list) {
3113	      if (!deficit.triggered) continue;
3114	      let rest = deficit.gap;
3115	      for (const src of sources) {
3116	        if (rest === 0n) break;
3117	        if (src.wh === deficit.wh || src.available === 0n) continue; // 缺货仓实存必低于目标，防御性跳过
3118	        const take = src.available < rest ? src.available : rest;
3119	        deficit.transfers.push({ from: src.wh, qty: take });
3120	        deficit.transferTotal += take;
3121	        src.available -= take; // 整份建议对来源的累计分配不超过可供量
3122	        rest -= take;
3123	      }
3124	      deficit.purchase = rest; // 剩余缺口即采购量（可为零）
3125	    }
3126	  }
3127	  return combos;
3128	}
