3130	function runReplenish(rest: string[], store: Store): void {
3131	  const args = parseArgs(rest, []);
3132	  if (args.positionals.length > 0) throw new UsageError('用法：replenish');
3133	  if (Object.keys(store.rules).length === 0) {
3134	    console.log('未配置任何补货规则，无补货建议（可先用 rule set 为商品与仓库设置下限与目标）。');
3135	    return;
3136	  }
3137	  const combos = computeReplenish(store);
3138	  const triggeredCount = combos.filter((c) => c.triggered).length;
3139	  console.log(`补货建议（规则 ${combos.length} 条，触发 ${triggeredCount} 条）：`);
3140	  for (const c of combos) {
3141	    console.log(
3142	      `商品 ${c.pid} 仓库 ${c.wh}：下限 ${c.min}，目标 ${c.target}，实存 ${c.onHand}，` +
3143	        `待到货合计 ${c.pending}，预计量 ${c.projected}，` +
3144	        (c.triggered ? `触发补货，缺口 ${c.gap}` : '未触发'),
3145	    );
3146	    if (c.triggered) {
3147	      for (const t of c.transfers) console.log(`  调拨 ${t.from} -> ${c.wh}：${t.qty}`);
3148	      console.log(`  调拨合计 ${c.transferTotal}，采购量 ${c.purchase}`);
