3571	
3572	  requests.forEach((r, i) => {
3573	    const pos = `第 ${i + 1}/${requests.length} 项`;
3574	    // 模拟阶段的业务拒绝同样标注列表位置与原因
3575	    const apply = (): ApplyOutcome => {
3576	      switch (r.kind) {
3577	        case 'doc': return ledger.applyDoc(r.req);
3578	        case 'count': return ledger.applyCount(r.req);
3579	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
3580	        case 'po': return ledger.applyPurchase(r.req);
3581	        case 'arrival': return ledger.applyArrival(r.req);
3582	        case 'cancel': return ledger.applyCancel(r.req);
3583	        case 'return': return ledger.applyReturn(r.req);
