    if (ret.poId !== poId || this.reversedOrigs.has(retId)) continue;
    for (const [pid, q] of Object.entries(ret.qty)) arrived[pid] = (arrived[pid] ?? 0n) - BigInt(q);
  }
  // 转入：目的采购单由创建它的未冲销转单获得的“已到货”（目的订购量恒等于转出量）
  const fromTransfer = this.pos[poId]?.fromTransfer;
  if (fromTransfer !== undefined && !this.reversedOrigs.has(fromTransfer)) {
    const t = this.transfers[fromTransfer];
    if (t !== undefined)
      for (const [pid, q] of Object.entries(t.qty)) arrived[pid] = (arrived[pid] ?? 0n) + BigInt(q);
  }
  return arrived;
}

/**
