  for (const [retId, ret] of Object.entries(store.returns)) {
    if (ret.poId !== poId || revOfOrig[retId] !== undefined) continue;
    for (const [pid, q] of Object.entries(ret.qty)) {
      arrived[pid] = (arrived[pid] ?? 0n) - BigInt(q);
