  this.reversedOrigs.add(origId);

  return {
    duplicate: false,
    header: `冲销单 ${revId} 提交成功，冲销采购转单 ${origId}（原采购单 ${t.origPo}，目的采购单 ${t.destPo}），共 ${pids.length} 种商品：`,
    lines: reportLines,
